let videoStream;
let mediaRecorder;
let videoChunks;
function getSupportedMimeType() {
  const mimeTypes = [
    { codec: "video/mp4;codecs=avc1,mp4a", mime: "video/mp4", extension: "mp4" },
    { codec: "video/webm;codecs=h264", mime: "video/webm", extension: "webm" },
    { codec: "video/webm", mime: "video/webm", extension: "webm" }
  ];
  for (let t of mimeTypes) {
    if (MediaRecorder.isTypeSupported(t.codec)) {
      return t;
    }
  }
  console.error("RECORDING NOT SUPPORTED");
  return void 0;
}
function startStopVideoRecording() {
  if (recordVideo) {
    if (mediaRecorder) {
      if (HUDElem) {
        HUDElem.classList.remove("recording");
      }
      setHUD(false);
      mediaRecorder.stop();
    }
    recordVideo = false;
  } else {
    videoChunks = [];
    const elem = document.getElementById("main");
    if (elem) {
      let mimeType = getSupportedMimeType();
      if (mimeType) {
        let extension = mimeType.extension;
        let blobType = mimeType.mime;
        videoStream = elem.captureStream(30);
        mediaRecorder = new MediaRecorder(videoStream, {
          videoBitsPerSecond: 25e6,
          mimeType: mimeType.codec
        });
        mediaRecorder.ondataavailable = function(e) {
          videoChunks.push(e.data);
        };
        mediaRecorder.onstop = function(e) {
          const blob = new Blob(videoChunks, { "type": blobType });
          const videoURL = URL.createObjectURL(blob);
          const link = document.createElement("a");
          link.download = `seekers-${fxhash}-${pixelWidth}x${pixelHeight}.${extension}`;
          link.href = videoURL;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          videoChunks = [];
        };
        mediaRecorder.start();
        console.log(mediaRecorder);
        recordVideo = true;
        setHUD(true);
        if (HUDElem) {
          HUDElem.classList.add("recording");
        }
      }
    }
  }
}
function setHUD(s) {
  showHUD = s;
  if (HUDElem) {
    if (s) {
      HUDElem.classList.remove("hidden");
      HUDElem.classList.add("visible");
    } else {
      HUDElem.classList.remove("visible");
      HUDElem.classList.add("hidden");
    }
  }
}
function toggleHUD() {
  setHUD(!showHUD);
}
